import torch

def masked_bc_loss(pred, target, valid):
    if (pred.ndim != 3 or pred.shape != target.shape
            or valid.shape != pred.shape[:2] or valid.dtype != torch.bool):
        raise ValueError('expected [B,H,D] and boolean [B,H]')
    mask = valid.unsqueeze(-1).expand_as(pred)
    if not bool(mask.any()):
        raise ValueError('no valid action')
    p, y = pred[mask], target[mask]
    if not bool(torch.isfinite(p).all() & torch.isfinite(y).all()):
        raise ValueError('nonfinite value at a valid action')
    return (p-y).square().mean()

