def body_delta(p_now, p_next, R):
    if len(p_now) != 3 or len(p_next) != 3 or len(R) != 3 or any(len(row) != 3 for row in R):
        raise ValueError('expected 3D position and 3x3 matrix')
    delta = [p_next[i] - p_now[i] for i in range(3)]
    return [sum(R[j][i] * delta[j] for j in range(3)) for i in range(3)]

