def window_indices(length, t, history, horizon):
    if min(length, history, horizon) <= 0 or not 0 <= t < length:
        raise ValueError('invalid window configuration')
    obs = [i if 0 <= i < length else None for i in range(t-history+1, t+1)]
    act = [i if 0 <= i < length else None for i in range(t, t+horizon)]
    return obs, act

import math

def add_noise(clean, noise, alpha_bar):
    if not 0 <= alpha_bar <= 1 or len(clean) != len(noise):
        raise ValueError('invalid coefficient or shape')
    a, b = math.sqrt(alpha_bar), math.sqrt(1-alpha_bar)
    return [a*x + b*z for x,z in zip(clean,noise)]

