def euler_integrate(x0, velocity, steps):
    if not isinstance(steps,int) or steps <= 0:
        raise ValueError('steps must be positive integer')
    x = float(x0)
    dt = 1.0/steps
    for k in range(steps):
        x = x + dt*velocity(x,k*dt)
    return x

