import torch

def flow_training_pair(noise, action, t):
    if noise.shape != action.shape or noise.ndim != 3 or t.shape != (len(noise),):
        raise ValueError('shape mismatch')
    if ((t < 0) | (t > 1)).any():
        raise ValueError('time outside [0,1]')
    t = t[:,None,None]
    return (1-t)*noise + t*action, action-noise

