import torch
from torch.nn import functional as F

def lora_forward(x,W,b,A,B,alpha):
    rank = A.shape[0]
    if rank <= 0 or B.shape != (W.shape[0],rank) or A.shape[1] != W.shape[1]:
        raise ValueError('invalid LoRA shape')
    return F.linear(x,W,b) + (alpha/rank)*F.linear(F.linear(x,A),B)

