import math
from collections import Counter

def sample_weights(tasks, desired):
    if not tasks or not desired:
        raise ValueError('empty data or distribution')
    if any(not math.isfinite(p) or p < 0 for p in desired.values()) or not math.isclose(sum(desired.values()),1.0):
        raise ValueError('invalid distribution')
    counts = Counter(tasks)
    if any(t not in desired for t in counts):
        raise ValueError('unknown task')
    if any(p > 0 and counts[t] == 0 for t,p in desired.items()):
        raise ValueError('positive probability without data')
    return [desired[t]/counts[t] for t in tasks]

