import torch

def training_statistics(x, train_mask):
    if x.ndim != 2 or train_mask.shape != (len(x),) or train_mask.dtype != torch.bool:
        raise ValueError('invalid shape or mask')
    train = x[train_mask]
    if len(train) == 0 or not torch.isfinite(train).all():
        raise ValueError('invalid training data')
    return train.mean(dim=0),train.std(dim=0,unbiased=False).clamp_min(1e-6)

