import torch

def macro_micro_success(scores, valid):
    if scores.ndim != 2 or scores.shape != valid.shape or valid.dtype != torch.bool:
        raise ValueError('invalid scores or mask')
    values = scores[valid]
    if not ((values == 0) | (values == 1)).all():
        raise ValueError('outcomes must be binary')
    counts = valid.sum(dim=1)
    if (counts == 0).any():
        raise ValueError('every task needs an evaluation')
    successes = torch.where(valid,scores,torch.zeros_like(scores)).sum(dim=1)
    return (successes/counts).mean(), successes.sum()/counts.sum()
